26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
28	    @Mapping(target = "membershipTier", expression = "java(formatMembershipTier(owner))")
29	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /**
33	     * Known city-to-region mappings. Keyed by the exact city name, the canonical region
34	     * string is returned for a listed city and {@code "UNKNOWN"} for anything else.
35	     */
36	    Map<String, String> CITY_REGIONS = Map.of(
37	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
38	
39	    /**
40	     * Derive an owner's locality from its city using the fixed {@link #CITY_REGIONS}
41	     * city-to-region table, returning the canonical region string or {@code "UNKNOWN"}
42	     * when the city is {@code null} or not present in the table.
43	     */
44	    default String formatLocality(Owner owner) {
45	        if (owner == null) {
46	            return null;
47	        }
48	        return CITY_REGIONS.getOrDefault(owner.getCity(), "UNKNOWN");
49	    }
50	
51	    /**
52	     * Determine an owner's membership tier: {@code "SILVER"} when the owner has no namesakes
53	     * (its {@code namesakeCount} is {@code 0}) and an email address is present, otherwise
54	     * {@code "BRONZE"}. A null or absent namesake count is treated as not being zero, so the
55	     * tier only reaches SILVER for an explicitly unique owner with an email.
56	     */
57	    default String formatMembershipTier(Owner owner) {
58	        if (owner == null) {
59	            return null;
60	        }
61	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
62	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
63	        return uniqueName && hasEmail ? "SILVER" : "BRONZE";
64	    }
65	
66	    /**
67	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
68	     * is the last two digits of the registration date year (e.g. {@code "TOW-SMI-0007-M26"}).
69	     * Returns {@code null} when either the customer code or registration date is absent, since
70	     * the number cannot be derived without both.
71	     */
72	    default String formatMembershipNumber(Owner owner) {
73	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
74	            return null;
75	        }
76	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
77	    }
78	
79	    /**
80	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
81	     */
82	    default String formatDisplayName(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        return owner.getLastName() + ", " + owner.getFirstName();
87	    }
88	
89	    /**
90	     * Format an owner's initials as the upper-cased first letters of the first and last
91	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
92	     */
93	    default String formatInitials(Owner owner) {
94	        if (owner == null) {
95	            return null;
96	        }
97	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
98	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
99	    }
