112	    /**
113	     * Normalize a postal address for storage into its canonical form (see
114	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
115	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
116	     * automatic method selection, so it only runs where a mapping explicitly references it via
117	     * {@code qualifiedByName}.
118	     */
119	    @Named("normalizeAddress")
