127	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
128	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
129	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
130	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
131	     */
132	    @Named("normalizeTelephone")
133	    default String normalizeTelephone(String telephone) {
134	        return E164Telephone.normalize(telephone);
135	    }
